{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "3-8",
      "explanation": "The method concatenates the user-provided searchKey directly into a SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially retrieve or manipulate data beyond their permissions.",
      "remediation": "Replace the dynamic query with a bind variable or use Database.queryWithBinds. For example: `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` and ensure searchKey is properly escaped or validated. This prevents injection while still enforcing USER_MODE for sharing."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Missing Field-Level Security Enforcement",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-10",
      "explanation": "The method updates the Contact.Phone field directly without checking field‑level security. If a user can invoke the method but lacks edit permission on Phone, the code will still modify the record, violating CRUD/FLS rules.",
      "remediation": "Add a check for field permissions before updating, e.g., use Security.stripInaccessible or explicitly verify that the current user has edit access to Contact.Phone before assigning the new value."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in Aura-enabled class",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared 'without sharing', so the SOQL query ignores record-level sharing rules. The method returns up to 200 recent Case records to any user with the permission set, potentially exposing cases they should not see.",
      "remediation": "Declare the class with 'with sharing' or 'inherited sharing', or add a WITH USER_MODE clause to the SOQL query. Additionally, consider filtering the query by the current user or relevant criteria to limit results to only those the user is allowed to view."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions in Permission Set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled, which provide far more access than needed for tier‑1 support agents. This violates least‑privilege principles and could allow unintended data exposure or unauthorized Apex execution.",
      "remediation": "Remove the ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions from the permission set. Grant only the necessary object permissions (Case read/edit) and minimal user permissions required for the support workflow."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest User Exposure via Aura Endpoint",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "1-10",
      "explanation": "The ContactSearchController class is exposed to a Guest User profile and is declared without sharing, allowing unauthenticated users to query all Contact records and retrieve sensitive fields (Email, Phone).",
      "remediation": "Remove the class from the Guest User profile, or change the class to 'with sharing' and enforce USER_MODE, and restrict the query to only public data or use a dedicated integration user with limited permissions."
    }
  ]
}
